import React, { useState, useEffect } from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import { supabase } from "./supabaseClient";
import UserDashboard from "./pages/UserDashboard";
import AdminDashboard from "./pages/AdminDashboard";
import Logs from "./pages/Logs";
import Analytics from "./pages/Analytics";
import LoginForm from "./components/LoginForm";
import "./App.css";

function App() {
  const [isAdmin, setIsAdmin] = useState(false);
  const [showLogin, setShowLogin] = useState(false);

  // restore session (optional)
  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => {
      if (data?.session) setIsAdmin(true);
    });
  }, []);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setIsAdmin(false);
    setShowLogin(false);
  };

  return (
    <Router>
      <header className="app-header">
        <div className="brand">
          <span className="brand-title">🏬 MyMall Smart Parking</span>
          <span className="live-pill">🟢 Live</span>
        </div>

        <div className="header-right">
          {!isAdmin ? (
            <button className="btn-login-small" onClick={() => setShowLogin(true)}>
              Admin Login
            </button>
          ) : (
            <>
              <button className="btn-header" onClick={() => window.location.href = "/dashboard"}>Dashboard</button>
              <button className="btn-header" onClick={() => window.location.href = "/logs"}>Logs</button>
              <button className="btn-header" onClick={() => window.location.href = "/analytics"}>Analytics</button>
              <button className="btn-logout" onClick={handleLogout}>Logout</button>
            </>
          )}
        </div>
      </header>

      {/* User dashboard is always rendered in the background */}


      {/* Modal login */}
      {!isAdmin && showLogin && (
        <div className="modal-overlay" onClick={() => setShowLogin(false)}>
          <div className="modal-card" onClick={(e) => e.stopPropagation()}>
            <LoginForm setIsAdmin={setIsAdmin} setShowLogin={setShowLogin} />
          </div>
        </div>
      )}

      <Routes>
        {isAdmin && (
          <>
            <Route path="/dashboard" element={<AdminDashboard />} />
            <Route path="/logs" element={<Logs />} />
            <Route path="/analytics" element={<Analytics />} />
          </>
        )}
        {/* fallback single admin route */}
        <Route path="*" element={isAdmin ? <AdminDashboard /> : <UserDashboard />} />
      </Routes>
    </Router>
  );
}

export default App;
